ogout.php')?>" title="Sign out" aria-label="Sign out"><?=ems_icon('logout')?></a></div></div></aside><div class="main-column"><header class="topbar"><button class="icon-button mobile-menu" id="menuToggle" type="button" aria-label="Open menu" aria-controls="sidebar" aria-expanded="false"><?=ems_icon('menu')?></button><div class="crumb">Workspace <span>/</span> <b><?=e($title)?></b></div><div class="top-actions"><span class="today-label"><?=e(date('D, M j'))?></span><?php if($role==='employee'):?><a class="icon-button notif-button" href="<?=e($base.'/employee/notifications.php')?>" aria-label="Notifications"><?=ems_icon('bell')?><?php if($unread):?><i></i><?php endif;?></a><?php endif;?><button class="theme-toggle icon-button" type="button" aria-label="Toggle theme"><?=ems_icon('theme')?></button><span class="top-divider"></span><span class="avatar small-avatar"><?=e(strtoupper(substr(current_user()['username'],0,1)))?></span><span class="top-user"><?=e(current_user()['username'])?><small><?=e(ucfirst($role))?></small></span><a class="signout-link" href="<?=e($base.'/logout.php')?>">Sign out</a></div></header><main class="content">
