function export_report(string $type): never {
    $pdo=db();$rows=[];$filename='ems-report.csv';
    if($type==='employees'){$rows=$pdo->query('SELECT e.employee_id,e.first_name,e.last_name,e.email,e.phone,d.department_name,e.designation,e.joining_date,e.employment_status FROM employees e LEFT JOIN departments d ON d.id=e.department_id ORDER BY e.employee_id')->fetchAll();$filename='employee-report.csv';}
    elseif($type==='attendance'){$q=$pdo->prepare('SELECT e.employee_id,CONCAT(e.first_name,\' \' ,e.last_name) employee,e.department_id,a.attendance_date,a.check_in,a.check_out,a.status,a.remarks FROM attendance a JOIN employees e ON e.id=a.employee_id WHERE a.attendance_date BETWEEN ? AND ? ORDER BY a.attendance_date DESC');$q->execute([$_GET['from']??date('Y-m-01'),$_GET['to']??date('Y-m-d')]);$rows=$q->fetchAll();$filename='attendance-report.csv';}
    elseif($type==='leaves'){$rows=$pdo->query('SELECT e.employee_id,CONCAT(e.first_name,\' \' ,e.last_name) employee,l.leave_type,l.start_date,l.end_date,l.status,l.reason FROM leaves l JOIN employees e ON e.id=l.employee_id ORDER BY l.created_at DESC')->fetchAll();$filename='leave-report.csv';}
    header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="'.$filename.'"');$out=fopen('php://output','w');if($rows){fputcsv($out,array_keys($rows[0]));foreach($rows as $r)fputcsv($out,$r);}fclose($out);exit;
}

function render_module(string $page,string $role,PDO $pdo,array $employees,array $departments,?array $self,string $q,int $deptFilter,string $statusFilter,string $dateFrom,string $dateTo,string $today,int $attToday,int $totalActive,int $pending,int $todayAbsent,string $base): void {
    $staff=in_array($role,['admin','hr'],true);$eid=(int)($self['id']??0);$link=fn($p)=>e($base.'/'.$role.'/'.$p.'.php');
    if($page==='dashboard'){
        if($staff){$rate=$totalActive?round(($attToday/$totalActive)*100):0;$recent=$pdo->query('SELECT a.*,e.first_name,e.last_name,e.employee_id,d.department_name FROM attendance a JOIN employees e ON e.id=a.employee_id LEFT JOIN departments d ON d.id=e.department_id WHERE a.attendance_date=CURDATE() ORDER BY a.check_in DESC LIMIT 5')->fetchAll();$activities=$role==='admin'?$pdo->query('SELECT l.*,u.username FROM activity_logs l LEFT JOIN users u ON u.id=l.user_id ORDER BY l.created_at DESC LIMIT 5')->fetchAll():[];?><section class="kpi-grid"><article class="kpi-card"><span class="kpi-icon purple"><?=ems_icon('users')?></span><span class="kpi-label">Active employees</span><strong><?=$totalActive?></strong><small>Across <?=count($departments)?> departments</small><a class="kpi-spark" href="<?=$link('employees')?>" aria-label="Open employees"><?=ems_icon('arrow-right')?></a></article><article class="kpi-card"><span class="kpi-icon green"><?=ems_icon('clock')?></span><span class="kpi-label">Present today</span><strong><?=$attToday?></strong><small><?=$rate?>% of active team</small><a class="kpi-spark" href="<?=$link('attendance')?>" aria-label="Open attendance"><?=ems_icon('arrow-right')?></a></article><article class="kpi-card"><span class="kpi-icon amber"><?=ems_icon('calendar')?></span><span class="kpi-label">Pending leave</span><strong><?=$pending?></strong><small>Requests awaiting review</small><a class="kpi-spark" href="<?=$link('leaves')?>" aria-label="Open leave requests"><?=ems_icon('arrow-right')?></a></article><article class="kpi-card"><span class="kpi-icon rose"><?=ems_icon('activity')?></span><span class="kpi-label">Absent today</span><strong><?=$todayAbsent?></strong><small>Recorded for today</small><a class="kpi-spark" href="<?=$link('attendance')?>" aria-label="Open attendance"><?=ems_icon('arrow-right')?></a></article></section><div class="dashboard-grid"><section class="panel span-two"><div class="panel-head"><div><h2>Today’s attendance</h2><p><?=e(date('l, F j'))?> · Recent check-ins</p></div><a class="text-link" href="<?=$link('attendance')?>">View attendance <span>→</span></a></div><?php if(!$recent):empty_state('clock','No attendance recorded yet','Today’s check-ins will appear here once they’re recorded.');else:?><div class="table-wrap"><table><thead><tr><th>EMPLOYEE</th><th>DEPARTMENT</th><th>CHECK IN</th><th>STATUS</th></tr></thead><tbody><?php foreach($recent as $r):?><tr><td><div class="person-cell"><span class="avatar tint-<?=$r['id']%4?>"><?=e(strtoupper(substr($r['first_name'],0,1).substr($r['last_name'],0,1)))?></span><span><b><?=e($r['first_name'].' '.$r['last_name'])?></b><small><?=e($r['employee_id'])?></small></span></div></td><td><?=e($r['department_name']??'—')?></td><td><?=e($r['check_in']?:'—')?></td><td><?=status_badge($r['status'])?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section><section class="panel"><div class="panel-head"><div><h2>Team snapshot</h2><p>Current headcount by department</p></div><a class="text-link" href="<?=$link('departments')?>">All departments <span>→</span></a></div><?php if(!$departments):empty_state('building','No departments yet','Create a department to start organizing your team.');else:?><div class="department-list"><?php $max=max(1,max(array_column($departments,'employee_count')));foreach(array_slice($departments,0,5) as $d):?><div class="dept-row"><span class="dept-dot"></span><span class="dept-name"><?=e($d['department_name'])?></span><b><?=$d['employee_count']?></b><div class="mini-bar"><i style="width:<?=round($d['employee_count']/$max*100)?>%"></i></div></div><?php endforeach;?></div><?php endif;?></section><?php if($role==='admin'):?><section class="panel span-two"><div class="panel-head"><div><h2>Recent activity</h2><p>Latest changes across your workspace</p></div><a class="text-link" href="<?=$link('activity')?>">All activity →</a></div><?php if(!$activities):empty_state('activity','Quiet for now','Important workspace activity will show up here.');else:?><div class="activity-list"><?php foreach($activities as $a):?><div class="activity-row"><span class="activity-dot"></span><span><b><?=e($a['username']??'System')?></b> <?=e(strtolower($a['action']))?> <small><?=e($a['details'])?></small></span><time><?=e(date('M j · H:i',strtotime($a['created_at'])))?></time></div><?php endforeach;?></div><?php endif;?></section><?php endif;?></div><?php
        }else{$a=$pdo->prepare('SELECT * FROM attendance WHERE employee_id=? AND attendance_date=CURDATE()');$a->execute([$eid]);$tod=$a->fetch();$le=$pdo->prepare('SELECT * FROM leaves WHERE employee_id=? AND leave_type<>\'Public Holiday\' ORDER BY created_at DESC LIMIT 3');$le->execute([$eid]);$myLeaves=$le->fetchAll();$departmentTasks=ems_department_overview((string)($self['department_code']??''));?><div class="welcome-banner"><div><span class="eyebrow">YOUR WORKSPACE</span><h2>Good <?=date('G')<12?'morning':(date('G')<17?'afternoon':'evening')?>, <?=e($self['first_name'])?></h2><p><?=e($self['designation'])?> · <?=e($self['department_name']??'Unassigned')?></p></div><div class="welcome-date"><b><?=date('d')?></b><span><?=date('M Y')?></span></div></div><section class="kpi-grid employee-kpis"><article class="kpi-card"><span class="kpi-icon purple"><?=ems_icon('clock')?></span><span class="kpi-label">Today</span><strong><?=$tod?e($tod['status']):'Not checked in'?></strong><small><?=$tod&&$tod['check_in']?'In at '.e($tod['check_in']):'Your attendance for today'?></small></article><article class="kpi-card"><span class="kpi-icon green"><?=ems_icon('calendar')?></span><span class="kpi-label">Leave requests</span><strong><?=count($myLeaves)?></strong><small>Recent requests on record</small></article><article class="kpi-card"><span class="kpi-icon amber"><?=ems_icon('bell')?></span><span class="kpi-label">Notifications</span><strong><?=(int)$pdo->query('SELECT COUNT(*) FROM notifications WHERE user_id='.(int)current_user()['id'].' AND is_read=0')->fetchColumn()?></strong><small>Unread updates</small></article></section><div class="employee-overview-grid"><section class="panel"><div class="panel-head"><div><span class="eyebrow">REPORTING LINE</span><h2>Your manager</h2><p>Your first point of contact for work and support.</p></div></div><?php if(!empty($self['manager_first_name'])):?><div class="manager-card"><span class="avatar tint-1"><?=e(strtoupper(substr($self['manager_first_name'],0,1).substr($self['manager_last_name'],0,1)))?></span><span><b><?=e($self['manager_first_name'].' '.$self['manager_last_name'])?></b><small><?=e($self['manager_designation']??'Manager')?> · <?=e($self['manager_employee_id']??'')?></small></span></div><?php else:?><p class="muted-text">No reporting manager is assigned yet. Please contact your administrator.</p><?php endif;?></section><section class="panel"><div class="panel-head"><div><span class="eyebrow">YOUR ROLE</span><h2><?=e($self['designation'])?></h2><p><?=e($self['department_name']??'Department not assigned')?><?=!empty($self['seniority_level'])?' · '.e($self['seniority_level']):''?></p></div></div><p class="role-summary"><?=e($self['job_responsibilities']??'Your role details are not configured yet. Ask your manager for your responsibilities.')?></p></section><section class="panel employee-department-overview"><div class="panel-head"><div><span class="eyebrow">TEAM OVERVIEW</span><h2>What your department does</h2><p><?=e($self['department_description']??'Your department overview has not been added yet.')?></p></div></div><ul class="responsibility-list"><?php foreach($departmentTasks as $task):?><li><?=e($task)?></li><?php endforeach;?></ul></section></div><section class="panel"><div class="panel-head"><div><h2>Recent leave requests</h2><p>Your time away at a glance</p></div><a class="text-link" href="<?=$link('leaves')?>">View all →</a></div><?php if(!$myLeaves)empty_state('calendar','No leave requests yet','When you need time away, you can request it here.');else{table_leaves($myLeaves,false);}?></section><?php }
    } elseif($page==='employees'){
        $sql='SELECT e.*,d.department_name,CONCAT(m.first_name,\' \',m.last_name) manager_name FROM employees e LEFT JOIN departments d ON d.id=e.department_id LEFT JOIN employees m ON m.id=e.manager_id WHERE 1=1';$args=[];if($q!==''){$sql.=' AND (e.employee_id LIKE ? OR e.first_name LIKE ? OR e.last_name LIKE ? OR e.email LIKE ? OR e.designation LIKE ?)';for($i=0;$i<5;$i++)$args[]="%$q%";}if($deptFilter){$sql.=' AND e.department_id=?';$args[]=$deptFilter;}if($statusFilter){$sql.=' AND e.employment_status=?';$args[]=$statusFilter;}$sql.=' ORDER BY e.id DESC LIMIT 100';$st=$pdo->prepare($sql);$st->execute($args);$list=$st->fetchAll();?><section class="panel"><form class="filter-bar" method="get"><label class="search-field"><?=ems_icon('search')?><input name="q" value="<?=e($q)?>" placeholder="Search by name, ID, email or role" aria-label="Search people"></label><select name="department"><option value="">All departments</option><?php foreach($departments as $d):?><option value="<?=$d['id']?>" <?=$deptFilter===$d['id']?'selected':''?>><?=e($d['department_name'])?></option><?php endforeach;?></select><select name="status"><option value="">Any status</option><option value="active" <?=$statusFilter==='active'?'selected':''?>>Active</option><option value="inactive" <?=$statusFilter==='inactive'?'selected':''?>>Inactive</option></select><button class="button secondary">Filter</button><span class="filter-count"><?=count($list)?> people</span></form><?php if(!$list):empty_state('users',$q?'No matching people':'Your people directory is empty',$q?'Try a different name, email or filter.':'Add your first employee to start building your directory.');else:?><div class="table-wrap"><table><thead><tr><th>PERSON</th><th>DEPARTMENT</th><th>DESIGNATION</th><th>REPORTS TO</th><?php if($role==='admin'):?><th>SALARY (INR)</th><?php endif;?><th>JOINED</th><th>STATUS</th><th></th></tr></thead><tbody><?php foreach($list as $r):?><tr><td><div class="person-cell"><span class="avatar tint-<?=$r['id']%4?>"><?=e(strtoupper(substr($r['first_name'],0,1).substr($r['last_name'],0,1)))?></span><span><b><?=e($r['first_name'].' '.$r['last_name'])?></b><small><?=e($r['employee_id'])?> · <a class="contact-link" href="mailto:<?=e($r['email'])?>"><?=e($r['email'])?></a><?php if(!empty($r['phone'])):?> · <a class="contact-link" href="tel:<?=e(preg_replace('/[^0-9+]/','',$r['phone']))?>"><?=e($r['phone'])?></a><?php endif;?></small></span></div></td><td><?=e($r['department_name']??'—')?></td><td><?=e($r['designation'])?></td><td><?=e($r['manager_name']??($r['designation']==='Chief Executive Officer'?'Company leadership':'Department manager'))?></td><?php if($role==='admin'):?><td><?=$r['salary_amount']===null?'Not set':'₹'.number_format((float)$r['salary_amount'],2)?></td><?php endif;?><td><?=e(date('M j, Y',strtotime($r['joining_date'])))?></td><td><?=status_badge(ucfirst($r['employment_status']))?></td><td><div class="row-actions"><button class="icon-button" type="button" title="Edit employee" aria-label="Edit <?=e($r['first_name'].' '.$r['last_name'])?>" data-edit-employee="<?=e(json_encode($role==='admin'?$r:array_diff_key($r,['salary_amount'=>true]),JSON_HEX_APOS|JSON_HEX_QUOT))?>"><?=ems_icon('edit')?></button><form method="post" class="inline-form"><?=csrf_field()?><input type="hidden" name="action" value="employee_status"><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="status" value="<?=$r['employment_status']==='active'?'inactive':'active'?>"><button class="button secondary small-button" type="submit"><?=$r['employment_status']==='active'?'Deactivate':'Activate'?></button></form></div></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section><?php
    } elseif($page==='departments'){
        $filter=array_values(array_filter($departments,fn($d)=>!$q||stripos($d['department_name'].' '.$d['department_code'],$q)!==false));?><div class="department-cards"><?php foreach($filter as $d):?><article class="department-card"><div class="dept-card-top"><span class="dept-emblem"><?=e(strtoupper(substr($d['department_code'],0,2)))?></span><?=status_badge(ucfirst($d['status']))?></div><h2><?=e($d['department_name'])?></h2><p><?=e($d['description']?:'No description provided.')?></p><div class="dept-card-foot"><span><?=e($d['department_code'])?></span><b><?=$d['employee_count']?> people</b></div><button class="text-link" data-edit-department="<?=e(json_encode($d,JSON_HEX_APOS|JSON_HEX_QUOT))?>">Edit department →</button></article><?php endforeach;?></div><?php if(!$filter):?><section class="panel"><?php empty_state('building','No departments yet','Add departments to group people and see team sizes.')?></section><?php endif;?><?php
    } elseif($page==='attendance'||$page==='my-attendance'){
        if(!$staff){$st=$pdo->prepare('SELECT * FROM attendance WHERE employee_id=? ORDER BY attendance_date DESC LIMIT 60');$st->execute([$eid]);$list=$st->fetchAll();$todayRow=null;foreach($list as $x)if($x['attendance_date']===$today)$todayRow=$x;$holidayName=ems_holiday_name($pdo,$today);?><section class="checkin-banner"><div><span class="eyebrow">TODAY · <?=e(date('M j, Y'))?></span><h2><?=e($holidayName?:((date('w')==='0')?'Weekly day off':($todayRow['status']??'Set your status')))?></h2><p><?=e($holidayName?'Public holiday · '.$holidayName:(date('w')==='0'?'Sunday is the weekly day off.':'Choose your current attendance status.'))?></p></div><?php if(date('w')!=='0'&&!$holidayName):?><form method="post" class="check-actions"><?=csrf_field()?><input type="hidden" name="action" value="attendance_self_status"><?php foreach(['Present','Absent','On Break'] as $attendanceStatus):?><button class="button <?=$todayRow&&$todayRow['status']===$attendanceStatus?'primary':'secondary'?>" name="status" value="<?=e($attendanceStatus)?>"><?=e($attendanceStatus)?></button><?php endforeach;?></form><?php endif;?></section><?php }else{$st=$pdo->prepare('SELECT a.*,e.employee_id,e.first_name,e.last_name,d.department_name FROM attendance a JOIN employees e ON e.id=a.employee_id LEFT JOIN departments d ON d.id=e.department_id WHERE a.attendance_date BETWEEN ? AND ? ORDER BY a.attendance_date DESC LIMIT 150');$st->execute([$dateFrom,$dateTo]);$list=$st->fetchAll();?><section class="panel"><form class="filter-bar"><label>From<input type="date" name="from" value="<?=e($dateFrom)?>"></label><label>To<input type="date" name="to" value="<?=e($dateTo)?>"></label><button class="button secondary">Apply dates</button><button class="button primary" type="button" data-modal-open="attendance-modal"><?=ems_icon('plus')?>Record attendance</button></form><?php }?><section class="panel"><div class="panel-head"><div><h2><?= $staff?'Attendance records':'Attendance history'?></h2><p><?=count($list)?> records · <?= $staff?e($dateFrom.' to '.$dateTo):'Most recent first'?></p></div></div><?php if(!$list):empty_state('clock','No attendance records','Attendance will appear here as it is recorded.');else:table_attendance($list,$staff);endif;?></section><?php
    } elseif($page==='leaves'||$page==='my-leave'){
        if($staff){$sql='SELECT l.*,e.employee_id,e.first_name,e.last_name,d.department_name,u.username reviewer FROM leaves l JOIN employees e ON e.id=l.employee_id LEFT JOIN departments d ON d.id=e.department_id LEFT JOIN users u ON u.id=l.reviewed_by WHERE 1=1';$args=[];if($statusFilter){$sql.=' AND l.status=?';$args[]=$statusFilter;}if($q){$sql.=' AND (e.first_name LIKE ? OR e.last_name LIKE ? OR e.employee_id LIKE ?)';array_push($args,"%$q%","%$q%","%$q%");}$sql.=' ORDER BY l.created_at DESC LIMIT 150';$st=$pdo->prepare($sql);$st->execute($args);$list=$st->fetchAll();?><?php if($role==='admin'):?><section class="panel"><div class="panel-head"><div><h2>Leave balances</h2><p>Set yearly paid and sick leave for an employee from their individual report.</p></div><a class="button secondary" href="<?=e($base.'/admin/reports.php')?>">Open individual reports</a></div><p class="muted-text">Casual Leave (LWP) has no balance limit. Sundays and public holidays are excluded from leave-day totals.</p></section><?php endif;?><section class="panel"><form class="filter-bar" method="get"><label class="search-field"><?=ems_icon('search')?><input name="q" value="<?=e($q)?>" placeholder="Search by name or employee ID" aria-label="Search leave requests by employee"></label><select name="status"><option value="">All requests</option><?php foreach(['Pending','Approved','Rejected'] as $s):?><option <?=$statusFilter===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select><button class="button secondary">Filter</button><span class="filter-count"><?=$pending?> pending</span></form><?php }else{$st=$pdo->prepare('SELECT * FROM leaves WHERE employee_id=? AND leave_type<>\'Public Holiday\' ORDER BY created_at DESC');$st->execute([$eid]);$list=$st->fetchAll();$balQ=$pdo->prepare('SELECT leave_type,total_days FROM leave_balances WHERE employee_id=? AND leave_year=?');$balQ->execute([$eid,(int)date('Y')]);$balRows=[];foreach($balQ->fetchAll() as $b)$balRows[$b['leave_type']]=$b['total_days'];?><div class="leave-balance-grid"><article class="balance-card"><div><b>Paid Leave</b><small>Used <?=ems_leave_usage($pdo,$eid,'Paid Leave',(int)date('Y'))['used']?> days · Pending <?=ems_leave_usage($pdo,$eid,'Paid Leave',(int)date('Y'))['pending']?> days</small></div><strong><?php $v=$balRows['Paid Leave']??null;echo $v===null?'Balance not set':number_format(max(0,(float)$v-ems_leave_usage($pdo,$eid,'Paid Leave',(int)date('Y'))['used']),1).' days left';?></strong></article><article class="balance-card"><div><b>Sick Leave</b><small>Used <?=ems_leave_usage($pdo,$eid,'Sick Leave',(int)date('Y'))['used']?> days · Pending <?=ems_leave_usage($pdo,$eid,'Sick Leave',(int)date('Y'))['pending']?> days</small></div><strong><?php $v=$balRows['Sick Leave']??null;echo $v===null?'Balance not set':number_format(max(0,(float)$v-ems_leave_usage($pdo,$eid,'Sick Leave',(int)date('Y'))['used']),1).' days left';?></strong></article><article class="balance-card"><div><b>Casual Leave (LWP)</b><small>Unlimited request count</small></div><strong>Unpaid</strong></article></div><?php }if(!$list):empty_state('calendar','No leave requests yet',$staff?'New leave requests will appear here.':'When you need time away, submit a request and track it here.');else:table_leaves($list,$staff,$role==='admin');endif;?></section><?php
    } elseif($page==='profile') { ?><div class="profile-layout"><section class="profile-hero panel"><span class="avatar profile-avatar tint-<?=$eid%4?>"><?=e(strtoupper(substr($self['first_name'],0,1).substr($self['last_name'],0,1)))?></span><div><span class="eyebrow"><?=e($self['employee_id'])?></span><h2><?=e($self['first_name'].' '.$self['last_name'])?></h2><p><?=e($self['designation'])?> · <?=e($self['department_name']??'Unassigned')?></p><?=status_badge(ucfirst($self['employment_status']))?></div></section><section class="panel"><div class="panel-head"><div><h2>Personal information</h2><p>Update the contact details on your profile.</p></div></div><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="profile_save"><label>First name *<input name="first_name" required value="<?=e($self['first_name'])?>"></label><label>Last name *<input name="last_name" required value="<?=e($self['last_name'])?>"></label><label>Work email *<input type="email" name="email" required value="<?=e($self['email'])?>"></label><label>Phone<input name="phone" value="<?=e($self['phone'])?>"></label><label>City<input name="city" value="<?=e($self['city'])?>"></label><label>Address<input name="address" value="<?=e($self['address'])?>"></label><div class="form-actions"><button class="button primary">Save profile</button></div></form></section></div><?php
    } elseif($page==='payroll'||$page==='my-pay') { require __DIR__.'/includes/module_payroll.php';
    } elseif($page==='reports') { require __DIR__.'/includes/module_person_report.php'; ?><div class="report-grid"><a class="report-card" href="<?=e($base.'/'.$role.'/reports.php?export=employees')?>"><span class="report-icon purple"><?=ems_icon('users')?></span><h2>People report</h2><p>Employee IDs, contact, department, designation and status.</p><span class="text-link">Download CSV ↓</span><small><?=count($employees)?> records</small></a><article class="report-card"><span class="report-icon green"><?=ems_icon('clock')?></span><h2>Attendance report</h2><p>Attendance for a selected date range.</p><form class="report-dates"><input type="date" name="from" value="<?=e($dateFrom)?>"><input type="date" name="to" value="<?=e($dateTo)?>"><button class="button secondary" formaction="<?=e($base.'/'.$role.'/reports.php')?>" formmethod="get" name="export" value="attendance">Download CSV ↓</button></form></article><a class="report-card" href="<?=e($base.'/'.$role.'/reports.php?export=leaves')?>"><span class="report-icon amber"><?=ems_icon('calendar')?></span><h2>Leave report</h2><p>Request types, periods, current decisions and reasons.</p><span class="text-link">Download CSV ↓</span><small><?=$pending?> pending requests</small></a></div><section class="panel"><div class="panel-head"><div><h2>People by department</h2><p>Current employee records grouped by team.</p></div></div><?php if(!$departments):empty_state('building','No department data','Create departments to build this report.');else:?><div class="bar-report"><?php $max=max(1,max(array_column($departments,'employee_count')));foreach($departments as $d):?><div class="bar-row"><span><?=e($d['department_name'])?></span><div class="bar-track"><i style="width:<?=round($d['employee_count']/$max*100)?>%"></i></div><b><?=$d['employee_count']?></b></div><?php endforeach;?></div><?php endif;?></section><?php
    } elseif($page==='holidays') { require __DIR__.'/includes/module_holidays.php';
    } elseif($page==='notices') { require __DIR__.'/includes/module_notices.php';
    } elseif($page==='users'){$list=$pdo->query('SELECT id,username,email,role,status,created_at FROM users ORDER BY created_at DESC')->fetchAll();?><section class="panel"><div class="panel-head"><div><h2>Workspace accounts</h2><p>Admin, HR and employee sign-in access.</p></div></div><div class="table-wrap"><table><thead><tr><th>ACCOUNT</th><th>ROLE</th><th>STATUS</th><th>CREATED</th></tr></thead><tbody><?php foreach($list as $u):?><tr><td><b><?=e($u['username'])?></b><small class="table-sub"><a class="contact-link" href="mailto:<?=e($u['email'])?>"><?=e($u['email'])?></a></small></td><td><?=e(ucfirst($u['role']))?></td><td><?=status_badge(ucfirst($u['status']))?></td><td><?=e(date('M j, Y',strtotime($u['created_at'])))?></td></tr><?php endforeach;?></tbody></table></div></section><?php
    } elseif($page==='activity'){$list=$pdo->query('SELECT l.*,u.username FROM activity_logs l LEFT JOIN users u ON u.id=l.user_id ORDER BY l.created_at DESC LIMIT 200')->fetchAll();?><section class="panel"><div class="panel-head"><div><h2>Workspace activity</h2><p>Most recent 200 events</p></div></div><?php if(!$list):empty_state('activity','No activity yet','Sign-ins and important changes will be recorded here.');else:?><div class="activity-list detailed"><?php foreach($list as $a):?><div class="activity-row"><span class="activity-dot"></span><span><b><?=e($a['username']??'System')?></b> <?=e(strtolower($a['action']))?><small><?=e($a['details'])?></small></span><time><?=e(date('M j, Y · H:i',strtotime($a['created_at'])))?></time></div><?php endforeach;?></div><?php endif;?></section><?php
    } elseif($page==='about') { ?><section class="panel settings-panel"><span class="eyebrow">ABOUT THE DEVELOPER</span><h2>Employment Management System</h2><p>Designed and developed by <strong>Shivshankar Gupta</strong>.</p><p>This project brings employee records, departments, attendance, leave requests, reports, and role-based access into one responsive application. It was built with PHP and MySQL, alongside HTML, CSS, JavaScript, and Bootstrap.</p><div class="setting-row"><span><b>Developer</b><small>Shivshankar Gupta</small></span><span class="badge muted">2026</span></div><div class="setting-row"><span><b>What this project does</b><small>Helps administrators manage people records and lets employees use self-service tools.</small></span></div></section><?php
    } elseif($page==='settings') { ?><section class="panel settings-panel"><span class="eyebrow">WORKSPACE IDENTITY</span><h2><?=e(setting('company_name','Employment Management System'))?></h2><p>Company work days are Monday through Saturday. Sunday is the weekly day off.</p><div class="setting-row"><span><b>Attendance schedule</b><small>Monday–Saturday are work days; Sunday is excluded.</small></span><span class="badge muted">6 days / week</span></div><div class="setting-row"><span><b>Leave categories</b><small>Employees can request Casual Leave (LWP), Paid Leave and Sick Leave. Paid and sick entitlements are set per employee in Reports.</small></span><a class="button secondary" href="<?=e($base.'/admin/reports.php')?>">Open reports</a></div><div class="setting-row"><span><b>Salary</b><small>Salary structures, deductions and payslips are managed in Payroll.</small></span><a class="button secondary" href="<?=e($base.'/admin/payroll.php')?>">Open payroll</a></div><p>To change the workspace name, edit the <code>company_name</code> value in the <code>settings</code> table using phpMyAdmin.</p><div class="setting-row"><span><b>Default timezone</b><small>Used for attendance timestamps</small></span><span class="badge muted"><?=e(setting('timezone','Asia/Kolkata'))?></span></div><div class="setting-row"><span><b>Session timeout</b><small>Inactive sessions expire for your security</small></span><span class="badge muted">60 minutes</span></div><div class="setting-row"><span><b>Theme preference</b><small>Stored in this browser</small></span><button class="button secondary theme-toggle">Switch theme</button></div></section><?php
    } elseif($page==='notifications'){$st=$pdo->prepare('SELECT * FROM notifications WHERE user_id=? ORDER BY created_at DESC LIMIT 100');$st->execute([current_user()['id']]);$list=$st->fetchAll();?><section class="panel"><div class="notification-list"><?php if(!$list):empty_state('bell','You’re all caught up','Account updates will appear here.');else:foreach($list as $n):?><article class="notification-row <?=$n['is_read']?'':'unread'?>"><span class="notification-glyph <?=e($n['type'])?>"><?=ems_icon('bell')?></span><div><b><?=e($n['title'])?></b><p><?=e($n['message'])?></p><small><?=e(date('M j, Y · H:i',strtotime($n['created_at'])))?></small></div><?php if(!$n['is_read']):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="notification_read"><input type="hidden" name="id" value="<?=$n['id']?>"><button class="button secondary small-button">Mark read</button></form><?php endif;?></article><?php endforeach;endif;?></div></section><?php }
}

function status_badge(string $s): string { return '<span class="badge '.e(badge_class($s)).'"><i></i>'.e($s).'</span>'; }
function empty_state(string $icon,string $title,string $desc): void { ?><div class="empty-state"><span class="empty-icon"><?=ems_icon($icon)?></span><h3><?=e($title)?></h3><p><?=e($desc)?></p></div><?php }
function table_leaves(array $list,bool $staff,bool $canEdit=false): void { ?><div class="table-wrap"><table><thead><tr><?php if($staff):?><th>EMPLOYEE</th><th>DEPARTMENT</th><?php endif;?><th>TYPE</th><th>DATES</th><th>REASON</th><th>STATUS</th><?php if($staff):?><th>REVIEW</th><?php endif;?><?php if($canEdit):?><th>EDIT</th><?php endif;?></tr></thead><tbody><?php foreach($list as $r):?><tr><?php if($staff):?><td><b><?=e(($r['first_name']??'').' '.($r['last_name']??''))?></b><small class="table-sub"><?=e($r['employee_id']??'')?></small></td><td><?=e($r['department_name']??'—')?></td><?php endif;?><td><?=e($r['leave_type'])?></td><td><?=e(date('M j',strtotime($r['start_date'])))?> – <?=e(date('M j, Y',strtotime($r['end_date'])))?></td><td class="reason-cell"><?=e($r['reason'])?></td><td><?=status_badge($r['status'])?></td><?php if($staff):?><td><?php if($r['status']==='Pending'):?><form method="post" class="review-actions"><?=csrf_field()?><input type="hidden" name="action" value="leave_review"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="text-action approve" name="status" value="Approved">Approve</button><button class="text-action reject" name="status" value="Rejected">Decline</button></form><?php else:?><small><?=e($r['reviewer']??'Reviewed')?></small><?php endif;?></td><?php endif;?><?php if($canEdit):?><td><button class="icon-button" type="button" title="Edit leave request" data-edit-leave="<?=e(json_encode($r,JSON_HEX_APOS|JSON_HEX_QUOT))?>" aria-label="Edit leave request"><?=ems_icon('edit')?></button></td><?php endif;?></tr><?php endforeach;?></tbody></table></div><?php }
function table_attendance(array $list,bool $staff): void { ?><div class="table-wrap"><table><thead><tr><?php if($staff):?><th>EMPLOYEE</th><?php endif;?><th>DATE</th><th>CHECK IN</th><th>CHECK OUT</th><th>STATUS</th><?php if($staff):?><th>DEPARTMENT</th><?php endif;?></tr></thead><tbody><?php foreach($list as $r):?><tr><?php if($staff):?><td><div class="person-cell"><span class="avatar tint-<?=($r['id']??1)%4?>"><?=e(strtoupper(substr($r['first_name'],0,1).substr($r['last_name'],0,1)))?></span><span><b><?=e($r['first_name'].' '.$r['last_name'])?></b><small><?=e($r['employee_id'])?></small></span></div><?php endif;?><td><?=e(date('M j, Y',strtotime($r['attendance_date'])))?></td><td><?=e($r['check_in']?:'—')?></td><td><?=e($r['check_out']?:'—')?></td><td><?=status_badge($r['status'])?></td><?php if($staff):?><td><?=e($r['department_name']??'—')?></td><?php endif;?></tr><?php endforeach;?></tbody></table></div><?php }
function render_modals(string $page,string $role,array $employees,array $departments,array $jobRoles,string $base): void { $staff=in_array($role,['admin','hr'],true); if($page==='employees'&&$staff):?><div class="modal-backdrop" id="employee-modal"><section class="modal-card"><div class="modal-head"><div><span class="eyebrow">PEOPLE DIRECTORY</span><h2 id="employee-modal-title">Add employee</h2></div><button class="icon-button" type="button" data-modal-close aria-label="Close"><?=ems_icon('close')?></button></div><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="employee_save"><input type="hidden" name="id" value=""><label>First name *<input name="first_name" required></label><label>Last name *<input name="last_name" required></label><label>Work email *<input type="email" name="email" required pattern="[A-Za-z0-9._-]+@ems[.]com" placeholder="first.last@ems.com"></label><label>Phone<input name="phone"></label><label>Department<select name="department_id"><option value="">Select department</option><?php foreach($departments as $d):?><option value="<?=$d['id']?>"><?=e($d['department_name'])?></option><?php endforeach;?></select></label><label>Reports to<select name="manager_id"><option value="">Department manager / None</option><?php foreach($employees as $manager):if(!$manager['manager_id']):?><option value="<?=$manager['id']?>" data-department="<?=$manager['department_id']?>" data-global="<?=$manager['department_id']===null?'1':'0'?>"><?=e($manager['first_name'].' '.$manager['last_name'].' · '.$manager['designation'])?></option><?php endif;endforeach;?></select></label><label>Designation *<input name="designation" list="job-role-options" required><datalist id="job-role-options"><?php foreach($jobRoles as $job):?><option value="<?=e($job['role_title'])?>" label="<?=e($job['department_name'].' · '.$job['seniority_level'].' · '.$job['responsibilities'])?>"></option><?php endforeach;?></datalist></label><?php if($role==='admin'):?><?php endif;?><label>Joining date *<input type="date" name="joining_date" required value="<?=date('Y-m-d')?>"></label><label>Status<select name="employment_status"><option value="active">Active</option><option value="inactive">Inactive</option></select></label><div class="form-actions"><button class="button secondary" type="button" data-modal-close>Cancel</button><button class="button primary">Add employee</button></div></form></section></div><?php endif;
if($page==='departments'&&$staff):?><div class="modal-backdrop" id="department-modal"><section class="modal-card"><div class="modal-head"><div><span class="eyebrow">TEAM STRUCTURE</span><h2 id="department-modal-title">Add department</h2></div><button class="icon-button" type="button" data-modal-close aria-label="Close"><?=ems_icon('close')?></button></div><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="department_save"><input type="hidden" name="id" value=""><label>Department name *<input name="department_name" required></label><label>Department code *<input name="department_code" required maxlength="20"></label><label class="wide">Description<textarea name="description" rows="3"></textarea></label><label>Status<select name="status"><option value="active">Active</option><option value="inactive">Inactive</option></select></label><div class="form-actions"><button class="button secondary" type="button" data-modal-close>Cancel</button><button class="button primary">Save department</button></div></form></section></div><?php endif;
if($page==='attendance'&&$staff):?><div class="modal-backdrop" id="attendance-modal"><section class="modal-card"><div class="modal-head"><div><span class="eyebrow">DAILY RECORD</span><h2>Record attendance</h2></div><button class="icon-button" type="button" data-modal-close aria-label="Close"><?=ems_icon('close')?></button></div><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="attendance_mark"><label class="wide">Employee<select name="employee_id" required><?php foreach($employees as $e):?><option value="<?=$e['id']?>"><?=e($e['employee_id'].' · '.$e['first_name'].' '.$e['last_name'])?></option><?php endforeach;?></select></label><label>Date<input type="date" name="attendance_date" required value="<?=date('Y-m-d')?>"></label><label>Status<select name="status"><?php foreach(['Present','Absent','Late','Half Day','Leave','On Break'] as $s):?><option><?=$s?></option><?php endforeach;?></select></label><label>Check in<input type="time" name="check_in"></label><label>Check out<input type="time" name="check_out"></label><label class="wide">Remarks<textarea name="remarks" rows="2"></textarea></label><div class="form-actions"><button class="button secondary" type="button" data-modal-close>Cancel</button><button class="button primary">Save record</button></div></form></section></div><?php endif;
if($page==='my-leave'&&$role==='employee'):?><div class="modal-backdrop" id="leave-modal"><section class="modal-card"><div class="modal-head"><div><span class="eyebrow">TIME AWAY</span><h2>Request leave</h2></div><button class="icon-button" type="button" data-modal-close aria-label="Close"><?=ems_icon('close')?></button></div><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="leave_apply"><label>Leave type<select name="leave_type"><?php foreach(['Casual Leave (LWP)','Paid Leave','Sick Leave'] as $s):?><option><?=$s?></option><?php endforeach;?></select></label><label>Start date<input type="date" name="start_date" required min="<?=date('Y-m-d')?>"></label><label>End date<input type="date" name="end_date" required min="<?=date('Y-m-d')?>"></label><label class="wide">Reason<textarea name="reason" rows="4" required placeholder="Share a short note for your manager"></textarea></label><div class="form-actions"><button class="button secondary" type="button" data-modal-close>Cancel</button><button class="button primary">Submit request</button></div></form></section></div><?php endif;
if($page==='leaves'&&$role==='admin'):?><div class="modal-backdrop" id="leave-edit-modal"><section class="modal-card"><div class="modal-head"><div><span class="eyebrow">ADMIN LEAVE CONTROL</span><h2>Edit leave request</h2></div><button class="icon-button" type="button" data-modal-close aria-label="Close"><?=ems_icon('close')?></button></div><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="leave_update"><input type="hidden" name="id"><label>Leave type<select name="leave_type"><?php foreach(['Casual Leave (LWP)','Paid Leave','Sick Leave','Annual','Personal Leave','Unpaid Leave','Compensatory Off'] as $t):?><option><?=e($t)?></option><?php endforeach;?></select></label><label>Status<select name="status"><?php foreach(['Pending','Approved','Rejected'] as $t):?><option><?=e($t)?></option><?php endforeach;?></select></label><label>Start date<input type="date" name="start_date" required></label><label>End date<input type="date" name="end_date" required></label><label class="wide">Reason<textarea name="reason" rows="3" required></textarea></label><div class="form-actions"><button class="button secondary" type="button" data-modal-close>Cancel</button><button class="button primary">Save leave changes</button></div></form></section></div><?php endif;
if($page==='users'&&$role==='admin'):?><div class="modal-backdrop" id="user-modal"><section class="modal-card"><div class="modal-head"><div><span class="eyebrow">WORKSPACE ACCESS</span><h2>Add account</h2></div><button class="icon-button" type="button" data-modal-close aria-label="Close"><?=ems_icon('close')?></button></div><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="user_create"><label>Username<input name="username" required></label><label>Work email<input type="email" name="email" readonly required value="@ems.com"></label><label>Role<select name="role"><option value="hr">HR</option><option value="admin">Admin</option></select></label><label>Password<input type="password" name="password" minlength="8" pattern="(?=.*[A-Z])(?=.*[a-z])(?=.*[0-9])(?=.*[^A-Za-z0-9]).{8,}" title="Use uppercase, lowercase, a number and a symbol." required></label><div class="form-actions"><button class="button secondary" type="button" data-modal-close>Cancel</button><button class="button primary">Create account</button></div></form></section></div><?php endif;
}
